import type { Source, DegreeAssessment } from "@/shared/contracts";
import type { RawAnalysis } from "@/shared/schemas";

// Explicitly constructed offline outputs: never runtime fallbacks or measured model results.
export function rawAssessments(
  sources: Source[],
): RawAnalysis["documentAssessments"] {
  return sources.map((s) => ({
    sourceId: s.id,
    status: "selected",
    explanation:
      "Offline contract fixture: operative policy covers the selected degree.",
    evidence: [
      { text: "Selected-degree scope.", passageIds: [s.passages[0].id] },
    ],
    missingInformation: [],
    exclusivelyOtherDegree: false,
    conflictingEvidence: false,
  }));
}

export function displayAssessments(sources: Source[]): DegreeAssessment[] {
  return sources.map((s) => ({
    sourceId: s.id,
    status: "selected",
    modelStatus: "selected",
    explanation:
      "OFFLINE TEST ONLY: supplied degree-scope interpretation, not generated by Gemini.",
    evidence: [{ ...s.passages[0], sourceName: s.name }],
    missingInformation: [],
    guardNotes: [],
  }));
}
